private.reference_solution:
#include <iostream>

void double_it(int& value) {
    value *= 2;
}

int main() {
    int a = 0;
    int b = 0;
    std::cin >> a >> b;
    double_it(b);
    std::cout << a << " " << b << std::endl;
    return 0;
}
